import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:go_router/go_router.dart';\nimport 'package:smooth_page_indicator/smooth_page_indicator.dart';\n\nclass OnboardingScreen extends ConsumerStatefulWidget {\n  const OnboardingScreen({Key? key}) : super(key: key);\n\n  @override\n  ConsumerState<OnboardingScreen> createState() => _OnboardingScreenState();\n}\n\nclass _OnboardingScreenState extends ConsumerState<OnboardingScreen> {\n  late PageController _pageController;\n  int _currentPage = 0;\n\n  final List<OnboardingItem> items = [\n    OnboardingItem(\n      title: 'Temukan Furnitur Impian',\n      description: 'Koleksi furnitur terlengkap dan terbaik pilihan untuk rumah Anda',\n      icon: Icons.home,\n      color: const Color(0xFF2C3E50),\n    ),\n    OnboardingItem(\n      title: 'Kualitas Premium',\n      description: 'Semua produk dijamin berkualitas tinggi dengan harga terjangkau',\n      icon: Icons.verified_user,\n      color: const Color(0xFFE74C3C),\n    ),\n    OnboardingItem(\n      title: 'Pengiriman Cepat',\n      description: 'Pengiriman gratis dan cepat ke seluruh Indonesia',\n      icon: Icons.local_shipping,\n      color: const Color(0xFF27AE60),\n    ),\n  ];\n\n  @override\n  void initState() {\n    super.initState();\n    _pageController = PageController();\n  }\n\n  @override\n  void dispose() {\n    _pageController.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      body: Column(\n        children: [\n          Expanded(\n            child: PageView.builder(\n              controller: _pageController,\n              onPageChanged: (index) {\n                setState(() => _currentPage = index);\n              },\n              itemCount: items.length,\n              itemBuilder: (context, index) {\n                return OnboardingPage(item: items[index]);\n              },\n            ),\n          ),\n          Padding(\n            padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 20),\n            child: Column(\n              children: [\n                SmoothPageIndicator(\n                  controller: _pageController,\n                  count: items.length,\n                  effect: const ExpandingDotsEffect(\n                    dotColor: Color(0xFFECF0F1),\n                    activeDotColor: Color(0xFF2C3E50),\n                    dotHeight: 8,\n                    dotWidth: 8,\n                  ),\n                ),\n                const SizedBox(height: 40),\n                Row(\n                  children: [\n                    if (_currentPage > 0)\n                      Expanded(\n                        child: OutlinedButton(\n                          onPressed: () {\n                            _pageController.previousPage(\n                              duration: const Duration(milliseconds: 300),\n                              curve: Curves.easeInOut,\n                            );\n                          },\n                          child: const Text('Kembali'),\n                        ),\n                      )\n                    else\n                      const SizedBox.shrink(),\n                    if (_currentPage > 0) const SizedBox(width: 12),\n                    Expanded(\n                      child: ElevatedButton(\n                        onPressed: () {\n                          if (_currentPage == items.length - 1) {\n                            context.go('/login');\n                          } else {\n                            _pageController.nextPage(\n                              duration: const Duration(milliseconds: 300),\n                              curve: Curves.easeInOut,\n                            );\n                          }\n                        },\n                        child: Text(_currentPage == items.length - 1 ? 'Mulai' : 'Selanjutnya'),\n                      ),\n                    ),\n                  ],\n                ),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass OnboardingPage extends StatelessWidget {\n  final OnboardingItem item;\n\n  const OnboardingPage({Key? key, required this.item}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      mainAxisAlignment: MainAxisAlignment.center,\n      children: [\n        Container(\n          width: 150,\n          height: 150,\n          decoration: BoxDecoration(\n            shape: BoxShape.circle,\n            color: item.color.withOpacity(0.2),\n          ),\n          child: Icon(\n            item.icon,\n            size: 80,\n            color: item.color,\n          ),\n        ),\n        const SizedBox(height: 40),\n        Text(\n          item.title,\n          style: const TextStyle(\n            fontSize: 28,\n            fontWeight: FontWeight.bold,\n            color: Color(0xFF2C3E50),\n          ),\n          textAlign: TextAlign.center,\n        ),\n        const SizedBox(height: 16),\n        Padding(\n          padding: const EdgeInsets.symmetric(horizontal: 24),\n          child: Text(\n            item.description,\n            style: const TextStyle(\n              fontSize: 16,\n              color: Color(0xFF7F8C8D),\n            ),\n            textAlign: TextAlign.center,\n          ),\n        ),\n      ],\n    );\n  }\n}\n\nclass OnboardingItem {\n  final String title;\n  final String description;\n  final IconData icon;\n  final Color color;\n\n  OnboardingItem({\n    required this.title,\n    required this.description,\n    required this.icon,\n    required this.color,\n  });\n}\n